export function computePickGrade(
  confidence: number,
  edgeScore: number
): PickGrade {
  if (confidence >= 85 && edgeScore >= 80) return "ELITE_PLAY";
  if (confidence >= 75 && edgeScore >= 65) return "STRONG_PLAY";
  if (confidence >= 65 && edgeScore >= 50) return "SOLID_PLAY";
  return "LEAN";
}

